# -*- coding: utf-8 -*-
PATTERNS_ANCHOR = '<pre class="l1"><span class="c">// Semaphore: 1,000 requests in flight, but only 5 touch the fragile API.</span>\nvar sem = make(chan struct{}, 5)\n\nfunc callVendor(ctx context.Context, id string) (*Quote, error) {\n    select {\n    case sem &lt;- struct{}{}:            <span class="c">// acquire a token</span>\n        defer func() { &lt;-sem }()      <span class="c">// release, always</span>\n    case &lt;-ctx.Done():\n        return nil, ctx.Err()         <span class="c">// give up rather than queue forever</span>\n    }\n    return vendor.Quote(ctx, id)\n}</pre>'

PATTERNS_ADDITION = '\n      <pre class="l2"><span class="c">// worker pool: N goroutines pull from one channel until it is closed</span>\nfunc workers(ctx context.Context, jobs &lt;-chan Job, n int) &lt;-chan Result {\n    out := make(chan Result)\n    var wg sync.WaitGroup\n    wg.Add(n)\n    for range n {\n        go func() {\n            defer wg.Done()\n            for j := range jobs {          <span class="c">// ends when jobs is closed</span>\n                out &lt;- process(ctx, j)\n            }\n        }()\n    }\n    go func() { wg.Wait(); close(out) }()  <span class="c">// close out only after every worker is done</span>\n    return out\n}\n\n<span class="c">// pipeline + fan-in: each stage is its own goroutine, joined by unbuffered channels</span>\nfunc pipeline(ctx context.Context, ids &lt;-chan string) &lt;-chan Order {\n    fetched := make(chan Raw)\n    go func() { defer close(fetched); for id := range ids { fetched &lt;- fetch(ctx, id) } }()\n\n    parsed := make(chan Order)\n    go func() { defer close(parsed); for r := range fetched { parsed &lt;- parse(r) } }()\n    return parsed                           <span class="c">// the caller ranges over this like any channel</span>\n}</pre>\n\n      <pre class="l3"><span class="c">// single-flight: 40 goroutines ask for the same key, the vendor sees ONE call</span>\nvar g singleflight.Group   <span class="c">// golang.org/x/sync/singleflight</span>\n\nfunc GetQuote(ctx context.Context, id string) (*Quote, error) {\n    v, err, shared := g.Do(id, func() (any, error) {\n        return vendor.Quote(ctx, id)        <span class="c">// only the first caller actually runs this</span>\n    })\n    if shared {\n        metrics.Inc("quote.dedup")          <span class="c">// the other 39 waited and got a copy of the same answer</span>\n    }\n    if err != nil {\n        return nil, err\n    }\n    return v.(*Quote), nil\n}</pre>'

TAXONOMY_ANCHOR = '<pre class="l2"><span class="c">// Wrap with context going up. Classify once, at the boundary that knows.</span>\nfunc (r *Repo) Get(ctx context.Context, id string) (*Order, error) {\n    row := r.db.QueryRowContext(ctx, q, id)\n    switch err := row.Scan(&amp;o); {\n    case err == nil:\n        return &amp;o, nil\n    case errors.Is(err, sql.ErrNoRows):\n        return nil, &amp;Error{Code: Terminal, Op: "repo.Get", Err: err}\n    case errors.Is(err, context.DeadlineExceeded), isConnErr(err):\n        return nil, &amp;Error{Code: Transient, Op: "repo.Get", Err: err}\n    default:\n        return nil, fmt.Errorf("repo.Get %s: %w", id, err)   <span class="c">// unknown: don\'t guess</span>\n    }\n}\n\n<span class="c">// errors.Join reports several independent failures without picking a winner.</span>\nfunc (c *Config) Validate() error {\n    var errs []error\n    if c.Port == 0 { errs = append(errs, errors.New("port is required")) }\n    if c.DSN == "" { errs = append(errs, errors.New("dsn is required")) }\n    return errors.Join(errs...)   <span class="c">// nil when the slice is empty</span>\n}</pre>'

TAXONOMY_ADDITION = '\n      <pre class="l1"><span class="c">// the four categories, made machine-readable -- Invalid was missing above</span>\ntype Code int\n\nconst (\n    Transient Code = iota   <span class="c">// timeout, 503, connection reset -- retry, if idempotent</span>\n    Terminal                <span class="c">// not found, forbidden -- fail fast, retrying is pure load</span>\n    Invalid                 <span class="c">// bad input -- a 4xx and a message, never an alert</span>\n)\n\nfunc (r *Repo) validate(id string) error {\n    if id == "" {\n        return &amp;Error{Code: Invalid, Op: "repo.Get", Err: errors.New("id is required")}\n    }\n    return nil\n}</pre>\n\n      <pre class="l3"><span class="c">// the fourth category is not a Code at all -- a bug is not a value to return, it is a panic</span>\nfunc (s *Server) handle(w http.ResponseWriter, r *http.Request) {\n    defer func() {\n        if v := recover(); v != nil {\n            log.Error("panic recovered", "route", r.URL.Path, "panic", v, "stack", string(debug.Stack()))\n            http.Error(w, "internal error", http.StatusInternalServerError)\n            metrics.Inc("panics")   <span class="c">// page someone -- this is a bug, not a retryable condition</span>\n        }\n    }()\n    s.routeFor(r)(w, r)\n}</pre>'
